use sha2::{Digest, Sha256};
use std::{fs, io, path::PathBuf, sync::Arc};

#[derive(Clone)]
pub struct ContentStore {
    root: Arc<PathBuf>,
}

impl ContentStore {
    pub fn new(root: PathBuf) -> io::Result<Self> {
        fs::create_dir_all(&root)?;
        Ok(Self {
            root: Arc::new(root),
        })
    }
    pub fn hash(bytes: &[u8]) -> String {
        Sha256::digest(bytes)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect()
    }
    pub fn valid_hash(hash: &str) -> bool {
        hash.len() == 64
            && hash
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
    }
    pub fn store(&self, bytes: &[u8]) -> io::Result<String> {
        let hash = Self::hash(bytes);
        self.store_verified(&hash, bytes)?;
        Ok(hash)
    }
    pub fn store_verified(&self, hash: &str, bytes: &[u8]) -> io::Result<()> {
        if !Self::valid_hash(hash) || Self::hash(bytes) != hash {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "content hash mismatch",
            ));
        }
        let path = self.root.join(hash);
        if path.exists() {
            return Ok(());
        }
        let temporary = self
            .root
            .join(format!(".{hash}.tmp-{}", std::process::id()));
        fs::write(&temporary, bytes)?;
        match fs::rename(&temporary, &path) {
            Ok(()) => Ok(()),
            Err(_error) if path.exists() => {
                let _ = fs::remove_file(temporary);
                Ok(())
            }
            Err(error) => Err(error),
        }
    }
    pub fn get(&self, hash: &str) -> io::Result<Option<Vec<u8>>> {
        if !Self::valid_hash(hash) {
            return Ok(None);
        }
        let path = self.root.join(hash);
        match fs::read(path) {
            Ok(bytes) if Self::hash(&bytes) == hash => Ok(Some(bytes)),
            Ok(_) => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "stored content failed verification",
            )),
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(None),
            Err(error) => Err(error),
        }
    }
    pub fn exists(&self, hash: &str) -> io::Result<bool> {
        Ok(self.get(hash)?.is_some())
    }
    pub fn delete(&self, hash: &str) -> io::Result<bool> {
        if !Self::valid_hash(hash) {
            return Ok(false);
        }
        match fs::remove_file(self.root.join(hash)) {
            Ok(()) => Ok(true),
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(false),
            Err(error) => Err(error),
        }
    }
    pub fn verify(&self, hash: &str) -> io::Result<bool> {
        self.get(hash).map(|value| value.is_some())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn content_is_verified_deduplicated_and_durable() {
        let root = std::env::temp_dir().join(format!("feltdb-content-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        let store = ContentStore::new(root.clone()).unwrap();
        let hash = store.store(b"customer content").unwrap();
        assert_eq!(store.store(b"customer content").unwrap(), hash);
        assert_eq!(
            ContentStore::new(root.clone())
                .unwrap()
                .get(&hash)
                .unwrap()
                .unwrap(),
            b"customer content"
        );
        assert!(store.store_verified(&hash, b"tampered").is_err());
        let _ = fs::remove_dir_all(root);
    }
}
